#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "correlation.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto n_vec = noarr::vector<'n'>();
constexpr auto m_vec = noarr::vector<'m'>();
constexpr auto p_vec = noarr::vector<'p'>();
constexpr auto q_vec = noarr::vector<'q'>();

struct tuning {
	// NOTE: We use a column-major layout for better cache locality when
	// computing statistics and correlations over rows (dimension 'n'):
	//
	// data: n x m  (rows: n, columns/features: m)
	//   - dimension 'm': features (outer)
	//   - dimension 'n': rows     (inner, contiguous)
	//
	// This makes accesses of the form data[*, fixed m] contiguous in memory,
	// which is exactly what we do in the main kernel when we sum or take
	// dot-products over rows.
	DEFINE_PROTO_STRUCT(data_layout,  n_vec ^ m_vec); // dims: 'm', 'n' (n is inner / contiguous)

	// corr: p x q (both run over features 0..M-1), row-major (q contiguous)
	DEFINE_PROTO_STRUCT(corr_layout, q_vec ^ p_vec);

	// 1D vectors over features
	DEFINE_PROTO_STRUCT(vec_layout,  m_vec);
} tuning;


// initialization function
// float_n <- N (number of rows in data)
// data[i][j] = (DATA_TYPE)(i*j)/M + i;
void init_array(num_t &float_n, auto data) {
	using namespace noarr;

	// N is the length in the 'n' dimension
	float_n = static_cast<num_t>(data | get_length<'n'>());

	// M is the length in the 'm' dimension (constant for all elements)
	const num_t M_len = static_cast<num_t>(data | get_length<'m'>());

	// Traverse all elements; the traversal order follows the structure
	// (here: outer 'm', inner 'n'), but we always access using named
	// indices 'n' and 'm', so the semantics are independent of layout.
	traverser(data).for_each([=](auto state) {
		auto [i, j] = get_indices<'n', 'm'>(state);

		data[state] =
			static_cast<num_t>(static_cast<num_t>(i * j) / M_len + static_cast<num_t>(i));
	});
}


// main computational kernel
//
// The computation follows the standard correlation computation:
//
// 1) mean[j]   = (1/N) * sum_i data[i][j]
// 2) stddev[j] = sqrt( (1/N) * sum_i (data[i][j] - mean[j])^2 )
//    stddev[j] = 1.0 if stddev[j] <= eps
// 3) Center and normalize:
//      data[i][j] = (data[i][j] - mean[j]) / (sqrt(N) * stddev[j])
// 4) corr = data^T * data
//
// We keep the high-level algorithm identical, but redesign the traversals
// so that:
//   - we traverse 'n' (rows) as the innermost dimension whenever we sum
//     or take dot products over rows,
//   - we precompute and reuse scaling factors,
//   - we minimize calls to get_length and expensive math inside loops.
//
[[gnu::flatten, gnu::noinline]]
void kernel_correlation(num_t float_n, auto data, auto corr, auto mean, auto stddev) {
	using namespace noarr;

	const num_t eps         = SCALAR_VAL(0.1);
	const num_t inv_float_n = SCALAR_VAL(1.0) / float_n;
	const num_t inv_sqrt_n  = SCALAR_VAL(1.0) / SQRT_FUN(float_n);

	// Number of features (M)
	std::size_t m_len = corr | get_length<'p'>();

#pragma scop

	// ------------------------------------------------------------------------
	// 1) mean[j] = (1/N) * sum_i data[i][j]
	// ------------------------------------------------------------------------
	// The data layout is column-major in terms of features:
	//   scalar<num_t> ^ n_vec ^ m_vec  => dims: 'm' (outer), 'n' (inner/contiguous)
	//
	// We exploit this by traversing (data, mean) jointly with a simple
	// for_each over all ('m','n'); the state carries both indices, but
	// mean[] only depends on 'm' and ignores 'n'. This gives a streaming
	// access pattern over 'n' for each fixed 'm'.
	// ------------------------------------------------------------------------

	// Initialize means to zero
	traverser(mean).for_each([=](auto s) {
		mean[s] = SCALAR_VAL(0.0);
	});

	// Accumulate column sums: for each (n,m), add data[n,m] to mean[m]
	traverser(data, mean).for_each([=](auto state) {
		mean[state] += data[state]; // mean ignores 'n' from state
	});

	// Scale by 1/N
	traverser(mean).for_each([=](auto s) {
		mean[s] *= inv_float_n;
	});

	// ------------------------------------------------------------------------
	// 2) stddev[j] = sqrt( (1/N) * sum_i (data[i][j] - mean[j])^2 )
	//    stddev[j] = 1.0 if stddev[j] <= eps
	//
	// Again we traverse row-wise (inner 'n'), accumulating into a 1D
	// stddev[] vector over features 'm'.
	// ------------------------------------------------------------------------

	// Initialize stddev accumulators to zero
	traverser(stddev).for_each([=](auto s) {
		stddev[s] = SCALAR_VAL(0.0);
	});

	// Accumulate squared deviations
	traverser(data, mean, stddev).for_each([=](auto state) {
		num_t diff = data[state] - mean[state]; // mean ignores 'n'
		stddev[state] += diff * diff;           // stddev ignores 'n'
	});

	// Finalize standard deviations and convert them into normalization
	// scale factors:
	//   stddev[j] = sqrt(variance_j);
	//   if stddev[j] <= eps: stddev[j] = 1.0;
	//   scale[j]  = 1 / (sqrt(N) * stddev[j]);
	// We store scale[j] directly into stddev[j] to avoid an extra array.
	traverser(stddev).for_each([=](auto s) {
		stddev[s] *= inv_float_n;
		stddev[s] = SQRT_FUN(stddev[s]);

		// Handle near-constant columns
		stddev[s] = (stddev[s] <= eps ? SCALAR_VAL(1.0) : stddev[s]);

		// Turn stddev into the scaling factor:
		//   1 / (sqrt(N) * stddev_effective)
		stddev[s] = inv_sqrt_n / stddev[s];
	});

	// ------------------------------------------------------------------------
	// 3) Center and reduce the column vectors:
	//      data[i][j] = (data[i][j] - mean[j]) * scale[j]
	// where scale[j] = 1 / (sqrt(N) * stddev_effective[j]) as computed above.
	//
	// Traversal order is again ('m','n'): for each feature we stream through
	// all rows contiguously, which is cache- and vectorization-friendly.
	// ------------------------------------------------------------------------
	traverser(data, mean, stddev).for_each([=](auto state) {
		num_t centered = data[state] - mean[state];
		data[state]    = centered * stddev[state];
	});

	// ------------------------------------------------------------------------
	// 4) Compute the m x m correlation matrix:
	//
	//   corr[i][i] = 1.0;
	//   for (i = 0; i < M-1; i++) {
	//     for (j = i+1; j < M; j++) {
	//       corr[i][j] = sum_k data[k][i] * data[k][j];
	//       corr[j][i] = corr[i][j];
	//     }
	//   }
	//   corr[M-1][M-1] = 1.0;
	//
	// Here, each column of 'data' (fixed feature index) is contiguous in
	// memory along 'n'. For every pair (i,j), we compute the dot product
	// by streaming through rows 'n' with unit stride.
	// ------------------------------------------------------------------------

	// Create views on data so that the feature index matches corr's 'p'/'q'
	//   data_p: dims 'p', 'n'  (feature index 'p')
	//   data_q: dims 'q', 'n'  (feature index 'q')
	auto data_p = data.get_ref() ^ noarr::rename<'m', 'p'>(); // dims: 'p', 'n'
	auto data_q = data.get_ref() ^ noarr::rename<'m', 'q'>(); // dims: 'q', 'n'

	// Outer loop over i = 0 .. M-1 (dimension 'p')
	// Use traverser on corr only; for each fixed 'p' index we then iterate
	// over all 'q' and, for j > i, perform a dot product over 'n'.
	traverser(corr).template for_dims<'p'>([=](auto trav_p) {
		auto state_p = trav_p.state();
		auto i = noarr::get_index<'p'>(state_p);

		// Only i < M-1 participate in the nested j-loop
		if (i < m_len - 1) {
			// corr[i][i] = 1.0;
			corr[noarr::idx<'p', 'q'>(i, i)] = SCALAR_VAL(1.0);

			// Middle loop over j = 0 .. M-1 (dimension 'q'),
			// we actually only use j > i.
			trav_p.template for_dims<'q'>([=](auto trav_pq) {
				auto state_pq = trav_pq.state();
				auto j = noarr::get_index<'q'>(state_pq);

				if (j > i) {
					// Initialize upper-triangular entry
					corr[state_pq] = SCALAR_VAL(0.0);

					// Inner loop over k = 0 .. N-1 (dimension 'n'):
					//   corr[i][j] += data[k][i] * data[k][j]
					//
					// We fix 'p' and 'q' in the data views to (i,j) and
					// traverse only the 'n' dimension; because of our
					// column-major layout, this walk over 'n' is
					// contiguous in memory for both columns.
					noarr::traverser(data_p, data_q)
						.order(noarr::fix(state_pq))
						.for_each([=](auto state_n) {
							// state_n has 'n' (and fixed 'p','q' via fix)
							corr[state_pq] += data_p[state_n] * data_q[state_n];
						});

					// Symmetry: corr[j][i] = corr[i][j]
					auto state_qp = noarr::idx<'p', 'q'>(j, i);
  					corr[state_qp] = corr[state_pq];
				}
			});
		}
	});

	// Final diagonal element: corr[M-1][M-1] = 1.0;
	if (m_len > 0) {
		auto last = m_len - 1;
		corr[noarr::idx<'p', 'q'>(last, last)] = SCALAR_VAL(1.0);
	}

#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input data
	num_t float_n;

	// set all relevant lengths
	auto set_lengths =
		noarr::set_length<'n'>(n) ^
		noarr::set_length<'m'>(m) ^
		noarr::set_length<'p'>(m) ^
		noarr::set_length<'q'>(m);

	// allocate bags for data, correlation matrix, mean, and stddev
	auto data   = noarr::bag(noarr::scalar<num_t>() ^ tuning.data_layout ^ set_lengths);
	auto corr   = noarr::bag(noarr::scalar<num_t>() ^ tuning.corr_layout ^ set_lengths);
	auto mean   = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout  ^ set_lengths);
	auto stddev = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout  ^ set_lengths);

	// initialize data
	init_array(float_n, data.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_correlation(float_n, data.get_ref(), corr.get_ref(), mean.get_ref(), stddev.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (correlation matrix) if requested
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'p' (row index) to top for a natural row-major printout
		noarr::serialize_data(std::cerr, corr.get_ref() ^ noarr::hoist<'p'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
