	using namespace noarr;

	const num_t eps           = SCALAR_VAL(0.1);
	const num_t inv_float_n   = SCALAR_VAL(1.0) / float_n;
	const num_t sqrt_float_n  = SQRT_FUN(float_n);

#pragma scop

	// ------------------------------------------------------------------------
	// mean[j] = 1/N * sum_i data[i][j]
	//
	// We first zero the mean vector and then perform a single traversal over
	// the 2D data structure that accumulates column sums. Since our data is
	// column-major ('n' contiguous, 'm' outer), each column is traversed
	// contiguously, which improves cache behavior and vectorization.
	// ------------------------------------------------------------------------

	// Zero-initialize mean
	traverser(mean).for_each([&](auto s_m) {
		mean[s_m] = SCALAR_VAL(0.0);
	});

	// Accumulate sums over the 'n' dimension for each feature 'm'
	traverser(data, mean).for_each([&](auto state) {
		// `mean` ignores 'n' and uses only 'm' from `state`
		mean[state] += data[state];
	});

	// Scale by 1/N
	traverser(mean).for_each([&](auto s_m) {
		mean[s_m] *= inv_float_n;
	});

