	// stddev[j] = sqrt( (1/N) * sum_i (data[i][j] - mean[j])^2 )
	//
	// Afterwards we overwrite `stddev[j]` with the *normalization factor*
	//   scale[j] = 1 / (sqrt(N) * stddev[j])
	// so that the centering/reduction step only performs multiplications.
	// This avoids an extra vector and reduces the number of divisions in the
	// inner loops.
	// ------------------------------------------------------------------------

	// Zero-initialize stddev accumulators
	traverser(stddev).for_each([&](auto s_m) {
		stddev[s_m] = SCALAR_VAL(0.0);
	});

	// Accumulate squared deviations
	traverser(data, mean, stddev).for_each([&](auto state) {
		const num_t val = data[state] - mean[state];
		stddev[state] += val * val;
	});

	// Finalize stddev and convert it into the scaling factor
	traverser(stddev).for_each([&](auto s_m) {
		// stddev_j = sqrt( (1/N) * sum_i (data[i][j] - mean[j])^2 )
		num_t s = stddev[s_m] * inv_float_n;
		s = SQRT_FUN(s);

		// Guard against very small variances
		if (s <= eps)
			s = SCALAR_VAL(1.0);

		// Store normalization factor:
		//   scale_j = 1 / (sqrt(N) * stddev_j)
		// We reuse the `stddev` bag to hold this factor.
		stddev[s_m] = SCALAR_VAL(1.0) / (sqrt_float_n * s);
	});

