	// Center and reduce the column vectors:
	//   data[i][j] = (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
	//
	// Since `stddev[j]` now stores the precomputed factor
	//   1 / (sqrt(float_n) * original_stddev[j]),
	// the normalization becomes:
	//   data[i][j] = (data[i][j] - mean[j]) * stddev[j]
	//
	// This pass traverses the data again in column-major order.
	// ------------------------------------------------------------------------
	traverser(data, mean, stddev).for_each([&](auto state) {
		const num_t centered = data[state] - mean[state];
		data[state] = centered * stddev[state];
	});

	// ------------------------------------------------------------------------
	// Compute the m x m correlation matrix:
	//
	//   corr[i][i]   = 1.0
	//   corr[i][j]   = sum_k data[k][i] * data[k][j]   for i < j
	//   corr[j][i]   = corr[i][j]
	//
	// We traverse all (i,j) pairs using a single traverser over `corr`. For
	// each upper‑triangular entry (i<j) we perform a dot product over the
	// 'n' dimension of the normalized data. Because the data layout is
	// column‑major ('n' contiguous), each dot product walks contiguous
	// memory for both participating feature columns.
	// ------------------------------------------------------------------------

	// Views on `data` where the feature index matches corr's 'p'/'q'
	auto data_p = data.get_ref() ^ noarr::rename<'m', 'p'>(); // dims: 'm','n' -> 'p','n'
	auto data_q = data.get_ref() ^ noarr::rename<'m', 'q'>(); // dims: 'm','n' -> 'q','n'

	noarr::traverser(corr).for_each([&](auto state_pq) {
		const auto [i, j] = noarr::get_indices<'p', 'q'>(state_pq);

		if (i == j) {
			// Diagonal is exactly one
			corr[state_pq] = SCALAR_VAL(1.0);
		} else if (i < j) {
			// Upper‑triangular element: corr[i][j] = dot(data[:,i], data[:,j])
			num_t acc = SCALAR_VAL(0.0);

			noarr::traverser(data_p, data_q)
				// Fix 'p' and 'q' to the current (i,j); only 'n' remains free
				.order(noarr::fix(state_pq))
				.for_each([&](auto state_n) {
					acc += data_p[state_n] * data_q[state_n];
				});

			// Write both symmetric positions
			corr[state_pq] = acc;
			corr[noarr::idx<'p', 'q'>(j, i)] = acc;
		}
	});

#pragma endscop
