	});

	// Scale by 1/N
	traverser(mean).for_each([&](auto sm) {
		mean[sm] *= inv_n;
	});


	// ------------------------------------------------------------------------
	// stddev[j] = sqrt( (1/N) * sum_i (data[i][j] - mean[j])^2 )
	// stddev[j] = 1.0 if stddev[j] <= eps
	// Again, traverse row-major for data.
	// ------------------------------------------------------------------------

	// Initialize stddev to zero
	traverser(stddev).for_each([&](auto sm) {
		stddev[sm] = SCALAR_VAL(0.0);
	});

	// Accumulate squared deviations per feature
	traverser(data, mean, stddev).template for_dims<'n'>([&](auto trav_n) {
		trav_n.for_each([&](auto state) {
			num_t val = data[state] - mean[state];
			stddev[state] += val * val;
		});
	});

	// Finalize stddev: divide by N, take sqrt, clamp with eps
	traverser(stddev).for_each([&](auto sm) {
		stddev[sm] *= inv_n;
		stddev[sm] = SQRT_FUN(stddev[sm]);
		stddev[sm] = stddev[sm] <= eps ? SCALAR_VAL(1.0) : stddev[sm];
	});

	// ------------------------------------------------------------------------
	// Precompute scaling factors into stddev:
	//   original: data[i][j] = (data[i][j] - mean[j]) / (sqrt(N) * stddev[j])
	//   here:     scale[j]   = 1 / (sqrt(N) * stddev[j])
	//             data[i][j] = (data[i][j] - mean[j]) * scale[j]
	//
	// We store "scale[j]" back into stddev[j] to avoid an extra array; stddev
	// is not used after the normalization, so this preserves observable behavior.
	// ------------------------------------------------------------------------

	traverser(stddev).for_each([&](auto sm) {
		stddev[sm] = inv_sqrt_n / stddev[sm];
	});


	// ------------------------------------------------------------------------
	// Center and reduce the column vectors:
	//   data[i][j] = (data[i][j] - mean[j]) * stddev[j]
	// where stddev[j] now holds the precomputed scale 1/(sqrt(N)*orig_stddev[j]).
	// Traverse row-major: outer 'n', inner 'm'.
	// ------------------------------------------------------------------------

	traverser(data, mean, stddev).template for_dims<'n'>([&](auto trav_n) {
		trav_n.for_each([&](auto state) {
			data[state] = (data[state] - mean[state]) * stddev[state];
		});
	});


	// ------------------------------------------------------------------------
	// Compute the m x m correlation matrix:
	//
	// corr[i][j] = sum_k data[k][i] * data[k][j]  (using normalized data)
	//
	// We:
	//   1. zero the full matrix,
	//   2. accumulate only the upper triangle (j > i) row by row (outer 'n'),
	//   3. mirror the upper triangle to the lower triangle and set the diagonal
	//      elements corr[i][i] = 1.0.
	//
	// For better data locality we iterate rows of 'data' (dimension 'n')
	// outermost so that each row stays in cache while we update many entries
	// of 'corr'.
	// Optionally, when M is divisible by CORR_TILE, we block the feature
	// dimensions ('p','q') to improve cache behavior of corr as well.
	// ------------------------------------------------------------------------

	// Matrix size M (number of features)
	std::size_t m_len = corr | get_length<'p'>(); // == corr | get_length<'q'>()

	// 1. Initialize full correlation matrix to zero
	traverser(corr).for_each([&](auto sc) {
		corr[sc] = SCALAR_VAL(0.0);
	});

	// Views of data with feature dimension renamed to match corr's 'p'/'q'
	auto data_p = data.get_ref() ^ noarr::rename<'m', 'p'>(); // dims: 'n', 'p'
	auto data_q = data.get_ref() ^ noarr::rename<'m', 'q'>(); // dims: 'n', 'q'

	// 2. Accumulate upper triangle: two variants
	if (m_len != 0 && (m_len % CORR_TILE) == 0) {
		// ---------------------------- Blocked variant ------------------------
		// Split feature dimensions into blocks of size CORR_TILE.
		// We only use the blocking when it exactly tiles the feature space,
		// avoiding any edge-case handling here.
		using noarr::lit;

		auto data_p_blk = data_p.get_ref()
			^ noarr::into_blocks<'p', 'P', 'p'>(lit<CORR_TILE>);
		auto data_q_blk = data_q.get_ref()
			^ noarr::into_blocks<'q', 'Q', 'q'>(lit<CORR_TILE>);
		auto corr_blk = corr.get_ref()
			^ noarr::into_blocks<'p', 'P', 'p'>(lit<CORR_TILE>)
			^ noarr::into_blocks<'q', 'Q', 'q'>(lit<CORR_TILE>);

		// Outer: rows 'n'
		noarr::traverser(data_p_blk, data_q_blk, corr_blk)
			.template for_dims<'n'>([&](auto trav_n) {

			// Next: feature blocks ('P' for rows, 'Q' for columns)
			trav_n.template for_dims<'P', 'Q'>([&](auto trav_nPQ) {

				// Inner: features inside the current pair of blocks ('p','q')
				trav_nPQ.for_each([&](auto state) {
					// state has: 'n', 'P', 'p', 'Q', 'q'
					std::size_t P = get_index<'P'>(state);
					std::size_t Q = get_index<'Q'>(state);
					std::size_t p_local = get_index<'p'>(state);
					std::size_t q_local = get_index<'q'>(state);

					// Global feature indices
					std::size_t i = P * CORR_TILE + p_local;
					std::size_t j = Q * CORR_TILE + q_local;

					// Only accumulate upper triangle, skip diagonal and lower
					if (j > i) {
						corr_blk[state] += data_p_blk[state] * data_q_blk[state];
					}
				});
			});
		});
	} else {
		// -------------------------- Unblocked variant ------------------------
		// Fall-back when M is not divisible by CORR_TILE. Still uses row-major
		// traversal for good locality.
		noarr::traverser(data_p, data_q, corr)
			.template for_dims<'n'>([&](auto trav_n) {

			// trav_n has 'n' fixed; remaining dims: 'p' and 'q'
			trav_n.for_each([&](auto state) {
				std::size_t i = get_index<'p'>(state);
				std::size_t j = get_index<'q'>(state);

				// Only accumulate upper triangle (j > i)
				if (j > i) {
					corr[state] += data_p[state] * data_q[state];
				}
			});
		});
	}

	// 3. Mirror upper triangle into lower triangle and set diagonal to 1.0
	noarr::traverser(corr).template for_dims<'p'>([&](auto trav_p) {
		auto state_p = trav_p.state();
		std::size_t i = get_index<'p'>(state_p);

		// Diagonal element corr[i][i] = 1.0
		corr[noarr::idx<'p', 'q'>(i, i)] = SCALAR_VAL(1.0);

		// Mirror: corr[j][i] = corr[i][j] for j > i
		trav_p.template for_dims<'q'>([&](auto trav_pq) {
			auto state_pq = trav_pq.state();
			std::size_t j = get_index<'q'>(state_pq);

			if (j > i) {
				num_t val = corr[state_pq];                // corr[i][j]
				corr[noarr::idx<'p', 'q'>(j, i)] = val;    // corr[j][i]
			}
		});
	});

#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input data
	num_t float_n;

	// set all relevant lengths
	auto set_lengths =
		noarr::set_length<'n'>(n) ^
		noarr::set_length<'m'>(m) ^
		noarr::set_length<'p'>(m) ^
		noarr::set_length<'q'>(m);

	// allocate bags for data, correlation matrix, mean, and stddev
	auto data   = noarr::bag(noarr::scalar<num_t>() ^ tuning.data_layout ^ set_lengths);
	auto corr   = noarr::bag(noarr::scalar<num_t>() ^ tuning.corr_layout ^ set_lengths);
	auto mean   = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout  ^ set_lengths);
	auto stddev = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout  ^ set_lengths);

	// initialize data
	init_array(float_n, data.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_correlation(float_n, data.get_ref(), corr.get_ref(), mean.get_ref(), stddev.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (correlation matrix) if requested
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'p' (row index) to top for a natural row-major printout
		noarr::serialize_data(std::cerr, corr.get_ref() ^ noarr::hoist<'p'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
