[[gnu::flatten, gnu::noinline]]
void kernel_correlation(num_t float_n, auto data, auto corr, auto mean, auto stddev) {
	using namespace noarr;

	const num_t eps     = SCALAR_VAL(0.1);
	const num_t inv_n   = SCALAR_VAL(1.0) / float_n;    // 1/N
	const num_t sqrt_n  = SQRT_FUN(float_n);            // sqrt(N)

#pragma scop

	// ------------------------------------------------------------------------
	// mean[j] = 1/N * sum_i data[i][j]
	//
	// Optimized for row-major access:
	//   - First zero mean[j]
	//   - Then traverse data row-by-row ('n' outer, 'm' inner, contiguous)
	//     and accumulate per-column sums.
	// ------------------------------------------------------------------------

	// Zero means
	traverser(mean).for_each([=](auto state_m) {
		mean[state_m] = SCALAR_VAL(0.0);
	});

	// Accumulate sums in a row-major way
	traverser(data, mean).template for_dims<'n'>([=](auto trav_n) {
		// trav_n has 'n' fixed, iterates all 'm'
		trav_n.for_each([=](auto state) {
			// state has 'n' and 'm'; mean ignores 'n'
			mean[state] += data[state];
		});
	});

	// Scale by 1/N
	traverser(mean).for_each([=](auto state_m) {
		mean[state_m] *= inv_n;
	});

	// ------------------------------------------------------------------------
	// stddev[j] = sqrt( (1/N) * sum_i (data[i][j] - mean[j])^2 )
	// stddev[j] = 1.0 if stddev[j] <= eps
	//
	// Again traverse row-by-row to exploit row-major layout.
	// ------------------------------------------------------------------------

	// Zero stddev
	traverser(stddev).for_each([=](auto state_m) {
		stddev[state_m] = SCALAR_VAL(0.0);
	});

	// Accumulate squared deviations, row-major over data
	traverser(data, mean, stddev).template for_dims<'n'>([=](auto trav_n) {
		trav_n.for_each([=](auto state) {
			num_t val = data[state] - mean[state];
			stddev[state] += val * val;
		});
	});

	// Finalize stddev: divide by N, sqrt, clamp by eps
	traverser(stddev).for_each([=](auto state_m) {
		stddev[state_m] = SQRT_FUN(stddev[state_m] * inv_n);
		stddev[state_m] = stddev[state_m] <= eps ? SCALAR_VAL(1.0) : stddev[state_m];
	});

	// ------------------------------------------------------------------------
	// Center and reduce the column vectors:
	//   data[i][j] = (data[i][j] - mean[j]) / (sqrt(N) * stddev[j])
	//
	// We traverse row-major ('n' then 'm') so each row is processed
	// with contiguous accesses along 'm'.
	// ------------------------------------------------------------------------
	traverser(data, mean, stddev).template for_dims<'n'>([=](auto trav_n) {
		trav_n.for_each([=](auto state) {
			data[state] -= mean[state];
			data[state] /= (sqrt_n * stddev[state]);
		});
	});

	// ------------------------------------------------------------------------
	// Compute the m x m correlation matrix:
	//
	// Original scalar pseudo-code (upper triangle, then symmetry):
	//
	// for (i = 0; i < M-1; i++) {
	//   corr[i][i] = 1.0;
	//   for (j = i+1; j < M; j++) {
	//     corr[i][j] = 0.0;
	//     for (k = 0; k < N; k++)
	//       corr[i][j] += data[k][i] * data[k][j];
	//     corr[j][i] = corr[i][j];
	//   }
	// }
	// corr[M-1][M-1] = 1.0;
	//
	// Optimized version below:
	//   - Use an outer-product style accumulation:
	//       for each row k, update all pairs (i,j), i<j:
	//         corr[i][j] += data[k][i]*data[k][j],
	//         corr[j][i] += same
	//   - Traversal order: 'n' (rows) outermost, then 'p' and 'q' for features.
	//   - This improves spatial locality on the (n x m) data matrix, while
	//     preserving exactly the same accumulation order per (i,j) pair.
	//   - Diagonal is set to 1.0 explicitly at the end (as in the original).
	// ------------------------------------------------------------------------

	// Reset full correlation matrix to zero; we will accumulate into it.
	traverser(corr).for_each([=](auto state_pq) {
		corr[state_pq] = SCALAR_VAL(0.0);
	});

	// Create views on data so that the feature index matches corr's 'p'/'q'
	auto data_p = data.get_ref() ^ noarr::rename<'m', 'p'>(); // dims: 'n', 'p'
	auto data_q = data.get_ref() ^ noarr::rename<'m', 'q'>(); // dims: 'n', 'q'

	// Outer loop over rows 'n'
	noarr::traverser(data_p, data_q, corr).template for_dims<'n'>([=](auto trav_n) {
		// For each fixed row k, iterate feature index 'p'
		trav_n.template for_dims<'p'>([=](auto trav_np) {
			auto state_np = trav_np.state();
			auto i = noarr::get_index<'p'>(state_np);

			// For each fixed (n, p=i), iterate feature index 'q'
			trav_np.template for_dims<'q'>([=](auto trav_npq) {
				auto state_npq = trav_npq.state(); // has 'n', 'p', 'q'
				auto j = noarr::get_index<'q'>(state_npq);

				// Only accumulate upper triangle; lower triangle is kept
				// symmetric by updating corr[j][i] alongside corr[i][j].
				if (j > i) {
					num_t val = data_p[state_npq] * data_q[state_npq];

					// corr[i][j] += val
					corr[state_npq] += val;

					// corr[j][i] += val (symmetry)
					auto state_qp = noarr::idx<'p', 'q'>(j, i);
					corr[state_qp] += val;
				}
			});
		});
	});

	// Set the diagonal elements corr[i][i] = 1.0 explicitly, as in the original
	noarr::traverser(corr).template for_dims<'p'>([=](auto trav_p) {
		auto state_p = trav_p.state();
		auto i = noarr::get_index<'p'>(state_p);

		auto diag_state = noarr::idx<'p', 'q'>(i, i);
		corr[diag_state] = SCALAR_VAL(1.0);
	});

#pragma endscop
