	// ------------------------------------------------------------------------

	const num_t sqrt_n = SQRT_FUN(float_n);

	traverser(data, mean, stddev).template for_dims<'n'>([&](auto trav_n) {
		trav_n.for_each([&](auto state_nm) {
			const num_t diff = data[state_nm] - mean[state_nm];
			data[state_nm] = diff / (sqrt_n * stddev[state_nm]);
		});
	});

	// ------------------------------------------------------------------------
	// 4) Compute the m x m correlation matrix:
	//
	//    for (i = 0; i < M-1; i++) {
	//      corr[i][i] = 1.0;
	//      for (j = i+1; j < M; j++) {
	//        corr[i][j] = 0.0;
	//        for (k = 0; k < N; k++)
	//          corr[i][j] += data[k][i] * data[k][j];
	//        corr[j][i] = corr[i][j];
	//      }
	//    }
	//    corr[M-1][M-1] = 1.0;
	//
	// Optimizations:
	//  - We first zero the whole corr matrix once, instead of setting
	//    corr[i][j] = 0.0 inside the i,j loop.
	//  - We compute only the upper triangle (j > i) and mirror it.
	//  - The accumulation over k (dimension 'n') is still performed
	//    using a Noarr traverser with a fixed (p,q) state.
	//  - The order in which each corr[i][j] is accumulated over k is
	//    unchanged, preserving per-entry floating-point semantics.
	// ------------------------------------------------------------------------

	// Zero the entire correlation matrix: corr[p][q] <- 0
	traverser(corr).for_each([&](auto state_pq) {
		corr[state_pq] = SCALAR_VAL(0.0);
	});

	// Create views on data so that the feature index matches corr's 'p'/'q'
	auto data_p = data.get_ref() ^ noarr::rename<'m', 'p'>(); // dims: 'n', 'p'
	auto data_q = data.get_ref() ^ noarr::rename<'m', 'q'>(); // dims: 'n', 'q'

	// Traverse all (p,q) pairs; compute only upper triangle (q > p)
	traverser(corr).template for_dims<'p'>([&](auto trav_p) {
		auto state_p = trav_p.state();
		auto i = noarr::get_index<'p'>(state_p);

		trav_p.template for_dims<'q'>([&](auto trav_pq) {
			auto state_pq = trav_pq.state();
			auto j = noarr::get_index<'q'>(state_pq);

			// Only compute corr[i][j] for j > i (upper triangle)
			if (j > i) {
				// Sum over k (dimension 'n'):
				//   corr[i][j] += data[k][i] * data[k][j]
				noarr::traverser(data_p, data_q)
					.order(noarr::fix(state_pq)) // fix 'p' = i, 'q' = j
					.for_each([&](auto state_n) {
						corr[state_pq] += data_p[state_n] * data_q[state_n];
					});

				// Enforce symmetry: corr[j][i] = corr[i][j]
				corr[noarr::idx<'p', 'q'>(j, i)] = corr[state_pq];
			}
		});
	});

	// Set the diagonal elements to 1.0:
	// corr[i][i] = 1.0  for all i
	traverser(corr).template for_dims<'p'>([&](auto trav_p) {
		auto state_p = trav_p.state();
		auto i = noarr::get_index<'p'>(state_p);
		auto diag_state = noarr::idx<'p', 'q'>(i, i);
		corr[diag_state] = SCALAR_VAL(1.0);
	});

#pragma endscop
}

